import pandas as pd,json,os,platform
import numpy,scipy,sklearn,matplotlib
O=os.path.dirname(__file__);a=pd.read_csv(O+'/construct_summary.csv');s=pd.read_csv(O+'/seed_features.csv');m=json.load(open(O+'/metrics.json'));pred=pd.read_csv(O+'/leave_construct_out_predictions.csv')
f='pp_nonlocal12_high_per_res';means=s.groupby('construct')[f].agg(['mean','std','min','max']);table=a.merge(means,left_on='construct',right_index=True);table['seeds']=table.construct.map(s.groupby('construct').size());table['result']=table.success.map({1:'成功',0:'失败'});table['score_mean_SD']=table.apply(lambda r:f'{r["mean"]:.6f} ± {r["std"]:.6f}',axis=1)
lines=['# PUF 构建成功／失败：CP 矩阵探索分析','', '## 结论','', '当前14种构建存在可区分的CP信号，主要集中在蛋白内部高概率非局部接触密度。3个成功构建的均值占据前三名；RNA接触特征缺乏稳定预测能力。按构建留出的浅层决策树在本批数据上14/14正确，汇总特征逻辑回归12/14正确。这些均为同批数据的探索性内部验证，尚无独立外部验证。','', '## 数据与标签','', '使用用户上传的 folds_2026_09_06_03_44.zip、folds_2026_09_06_03_46.zip。14种构建，成功3种、失败11种，共56个seed任务、280个预测模型。所有提供的模型均纳入；无筛选最高ranking模型。以用户明确列出的3种为成功，其余全部为失败，包含2种PUF11构建。RNA均为13nt AUGGAGGACGUGC。','', 'R123_R567_R567_R678为seed 2–6，共5个；R123_R567_R6loopR7_R5678为seed 1–3，共3个；其余各4个seed，每seed均5个模型。同构建所有seed的输入蛋白序列一致。矩阵均对称，元素有限且位于[0,1]，蛋白token数与序列长度一致。','', '首先在同一seed内平均5个模型的特征，再对各seed等权平均。独立实验标签数为14，280个结构仅为技术预测重复。没有将同一构建的不同模型分到训练集和测试集。','', '## 指标定义','', '直接使用 full_data JSON 的 contact_probs，未用PAE或坐标距离代替CP。A链为蛋白，B链为RNA。蛋白内部指标：','', r'$$S=\frac{1}{L}\sum_{i<j,\;j-i\geq12}\mathbf{1}(CP_{ij}>0.5)$$','', 'L为蛋白总残基数；只计上三角，每对残基仅计一次，排除序列距离小于12的残基对。S是每残基的高概率非局部接触对数，数值可以超过1。此处“非局部”是操作性定义，无法单凭该指标划定repeat之间的接触。均值±SD为不同seed均值的分布，SD不代表生物学实验误差。','', '## 完整构建排序','','\n'.join(['| ID | 构建 | 标签 | seed数 | S均值 ± seed SD |','|---|---|---|---:|---:|']+['| '+' | '.join(map(str,row))+' |' for row in table[['ID','construct','result','seeds','score_mean_SD']].itertuples(index=False,name=None)]),'', '构建均值中，成功最低为1.316895，失败最高为1.307322。全数据两组边界中点为1.312108，仅可作为本批数据的探索性参考阈值。种子层面有重叠：成功R6R7构建最低1.308594，失败R5loop67_R678最高1.317919，失败R6loopR7_R5678最高1.315992。不能把1.3121当作通用成功阈值。','', '## 留出验证','', '每次完整留出1种构建，使用其余13种训练。逻辑回归的标准化仅在训练折拟合；固定C=0.1，class_weight=balanced，无外层测试集调参。决策树max_depth=1，class_weight=balanced；在每个训练折重新从52个CP特征中选择特征和阈值。蛋白分箱为按长度均分的12个区间，并不代表真实repeat注释。','', '| 方法 | 留出结果 | AUC | 平衡准确率 | 精确置换p |','|---|---|---:|---:|---:|','| CP汇总逻辑回归（14特征） | TP=3, TN=9, FP=2, FN=0 | 0.9091 | 0.9091 | 0.0412 |','| RNA接触轮廓逻辑回归（26特征） | TP=0, TN=7, FP=4, FN=3 | 0.0000 | 0.3182 | 1.0000 |','| 仅蛋白长度逻辑回归 | TP=0, TN=4, FP=7, FN=3 | 0.2121 | 0.1818 | 0.7637 |','| 训练折内选特征与阈值的单层树 | TP=3, TN=11, FP=0, FN=0 | 未作为检验指标 | 1.0000 | 0.0110 |','', '置换穷举C(14,3)=364种标签分配；每次重新训练全部留出折。逻辑回归使用AUC作单侧置换统计量，决策树使用平衡准确率。上述p值未对模型间的多重比较或分析流程的后续选择进行校正，因此仅作探索性证据。RNA轮廓AUC=0是本小样本留出结果，不支持事后翻转分数并宣称预测成功。所有逻辑回归分数未校准，不能当作真实构建成功概率。','', '树在14个训练折均选中S指标；阈值介于1.308415–1.312644。逐折选择记录见nested_stump_predictions.csv。单层树是看到蛋白内部接触信号后增加的探索性分析，流程选择本身未被置换检验覆盖。','', '单指标全数据排名：3种不同序列距离阈值（4、12、24）的高概率接触密度均AUC=1。以52个CP特征中的最强双向AUC为统计量，穷举标签并对整次特征搜索校正后p=0.0934。这个检验与上述决策树检验的统计量和零分布不同，应并列呈现。','', '逻辑回归误判的两个失败构建：R123_R567_R5loop67_R678（留出分数0.7936）与R123_R567_R6loopR7_R5678（0.6785）。它们也是S指标最接近成功组的两个失败构建。','', '## 生物学解释与局限','', '成功构建的蛋白内部高概率接触密度较高，支持进一步检查重复模块的内部堆积和连接处接触。当前计算尚未做序列对齐和repeat边界映射，不能指定某段CCR或某个残基为决定因素，也不能把CP密度等同于实验稳定性。','', '成功R5loop67_loopR678的蛋白–RNA CP总和约43.795，低于多个失败构建的约51；其ipTM约0.890，也低于若干失败构建。因此“RNA结合接触更强／ipTM更高就一定构建成功”无法解释这些标签。','', '如果构建成功指克隆、转化或测序确认，当前关联无法直接解释DNA层面的重复序列重组、引物问题等失败原因。如果标签指表达或功能验证成功，也需要对应实验数据来定位因果环节。当前标签定义按用户原话保留。','', '只有3个成功构建，且3者来自相近设计家族，存在架构混杂。长度对照表现差并不能排除序列和架构混杂。非局部接触阈值CP>0.5尚未独立验证；全长序列不同，未直接flatten拼接不同尺寸的原始矩阵。建议冻结指标与验证流程，用下一批具有明确失败环节记录的构建进行独立验证，尤其关注本批两个边界失败构建。','', '## 图与复现','', 'CP_comparison：A为S的构建均值±seed SD，淡点为各seed均值；B为蛋白–RNA CP总和；C为CP汇总逻辑回归的逐构建留出分数，虚线0.5。蓝色菱形为成功，橙色圆形为失败。ID映射见上表。RNA_CP_heatmap为每个RNA位置在蛋白维度求和的CP，统一色标，未对每行单独归一化。','', '运行：将原始zip放在upload/下；依次执行 python results/analyze.py、python results/validate_plot.py、python results/write_report.py。归档保持results/目录。原始zip不重复打包。mean_protein_rna_CP.npz保存各构建平均蛋白–RNA矩阵；完整蛋白内部矩阵可从原始JSON重新读取。','']
open(O+'/PUF_CP_report.md','w').write('\n'.join(lines))
